const { id1, iso3, attr_cube1, variant_name1 } = variables;
const { subnationalComplexityAvailability } = formatters;
const cubes = resp.cubes;

// Filtrar los cubos del país
const countryCubes = cubes.filter(d => d.name === attr_cube1);
const hasSubnatData = countryCubes.length > 0;

// Extraer niveles jerárquicos
let dimensionNames = ["Time", "Partner", "Product", "Subnat Geography"];
if (variant_name1 === "Mexico Municipalities") {
  dimensionNames = ["Time", "Country", "Product", "Subnat Geography"];
}

const extractLevelNames = (data, dimensionNames) => ({
  name: data.name,
  levels: Object.fromEntries(
    dimensionNames.map(dimName => {
      const dim = data.dimensions.find(d => d.name === dimName);
      const cleanName = dimName.replace(/ Official$/, ""); 
      const levels = dim
        ? dim.hierarchies.flatMap(h =>
            h.levels.map(l => l.name.replace(/ Official$/, ""))
          )
        : (dimName === "Year" && iso3 === "mex") ? ["Year"] : [];
      return [cleanName, levels];
    })
  )
});

const extractedLevels = hasSubnatData
  ? countryCubes.map(cube => extractLevelNames(cube, dimensionNames))
  : [];


const currencySignDict = {
  can: "C$", chn: "$", deu: "€", jpn: "¥", rus: "$", esp: "€", bra: "$",
  gbr: "£", usa: "$", mys: "MYR", zaf: "ZAR", kor: "$", swe: "SEK",
  phl: "$", bol: "$", bel: "€", nld: "€", irl: "€", ind: "$", fra: "€",
  prt: "€", ecu: "$", ury: "$", chl: "$", tur: "$", sau: "SAU",
  ita: "€", prt: "€", vtm: "$", aus: "AUD"
};
const currencyAbbDict = {
  can: "CAD (C$)", chn: "USD ($)", deu: "EUR (€)", ita: "EUR (€)", jpn: "JPY (¥)",
  rus: "USD ($)", esp: "EUR (€)", bra: "USD ($)", gbr: "GBP (£)", usa: "USD ($)",
  mys: "MYR", zaf: "ZAR", kor: "USD ($)", swe: "SEK", phl: "USD ($)", bol: "USD ($)",
  bel: "EUR (€)", nld: "EUR (€)", irl: "EUR (€)", ind: "USD ($)", fra: "EUR (€)",
  prt: "EUR (€)", ecu: "USD ($)", chl: "USD ($)", tur: "USD ($)",
  nor: "NOK", aus: "AUD", qat: "QAR", prt: "EUR (€)", vtm: "USD ($)",
};


const cubeParts = attr_cube1.split("_");
const isHS = cubeParts.slice(-2).join("_") === "m_hs";
const classification = cubeParts.at(-1);

return {
  hasSubnatData,
  hasNotSubnatData: !hasSubnatData,
  countryCubes,
  extractedLevels,
  iso3,
  currencySubnat: currencySignDict[iso3] || "$",
  currencyAbbSubnat: currencyAbbDict[iso3] || "$",
  isHS,
  classification,
  hasComplexitySubnat: subnationalComplexityAvailability(attr_cube1)
};

// Genera el diccionario de índices basado en los niveles presentes
const generateDictionary = (array) => {
  const dictionary = {};

  array.forEach((dataset, index) => {
    const levels = dataset.levels;

    Object.keys(levels).forEach((level) => {
      if (levels[level].length > 0) {
        dictionary[level] = index;
      }
    });
  });
  return dictionary;
};

// Permite sobrescribir valores del diccionario por clave
const overwriteIndexDict = (dictionary, overwriteMap = {}) => {
  Object.keys(overwriteMap).forEach((key) => {
    dictionary[key] = overwriteMap[key];
  });
};

// Encuentra el índice con la mayor cantidad de niveles para una categoría
const getMaxLevelIndex = (array, category) => {
  let maxLen = -1;
  let maxIndex = -1;
  array.forEach((dataset, idx) => {
    const len = dataset.levels?.[category]?.length || 0;
    if (len > maxLen) {
      maxLen = len;
      maxIndex = idx;
    }
  });
  return maxIndex;
};

// Reglas por país para extraer niveles
const extractionRules = {
  mex: {
    "Year": "last",
    "HS Product": "last",
    "Country": "last",
    "Subnat Geography": "last"
  },
  default: {
    "Time": "last",
    "Product": "penultimate",
    "Partner": "last",
    "Subnat Geography": "last"
  }
};

// Función para seleccionar un nivel según la regla
const selectLevel = (levels = [], rule = "penultimate") => {
  if (levels.length === 0) return false;

  if (rule === "last") return levels[levels.length - 1];
  if (rule === "penultimate") return levels[levels.length - 2] || levels[0];
  if (typeof rule === "number") return levels[rule] || false;

  return false;
};

// Obtiene la regla apropiada para un país y dimensión
const getRuleFor = (countryIso, dimension) => {
  return (
    (extractionRules[countryIso] && extractionRules[countryIso][dimension]) ||
    extractionRules.default[dimension] ||
    "last"
  );
};

const extractSubnationalData = (variables, dictionary, category) => {
  const { extractedLevels = [] } = variables || {};
  const index = dictionary[category];
  const subnatDataset = extractedLevels[index] || { levels: {}, name: '' };

  const levels = (subnatDataset.levels[category] || []).filter(
    level => level !== 'Previous Province'
  );

  return {
    datasetName: subnatDataset.name?.length > 0 ? subnatDataset.name : false,
    levels
  };
};

// Dimensiones por país
let dimensionNames = ["Time", "Partner", "Product", "Subnat Geography"];


const indexDict = generateDictionary(variables.extractedLevels);

/*if (variables["variant_name1"] === "Mexico Municipalities") {
  const yearIndex = getMaxLevelIndex(variables.extractedLevels, "Year");
  overwriteIndexDict(indexDict, { "Year": yearIndex });
}*/


const resultTime = extractSubnationalData(variables, indexDict, dimensionNames[0]);
const resultPartner = extractSubnationalData(variables, indexDict, dimensionNames[1]);
const resultProduct = extractSubnationalData(variables, indexDict, dimensionNames[2]);
const resultGeo = extractSubnationalData(variables, indexDict, dimensionNames[3]);

const iso = variables.iso3 || "default";

const lastTimeLevel = selectLevel(resultTime.levels, getRuleFor(iso, dimensionNames[0]));
const lastPartnerLevel = selectLevel(resultPartner.levels, getRuleFor(iso, dimensionNames[1]));
const lastProductLevel = selectLevel(resultProduct.levels, getRuleFor(iso, dimensionNames[2]));
const lastGeoLevel = selectLevel(resultGeo.levels, getRuleFor(iso, dimensionNames[3]));

// Lista de nombres de datasets
const datasetsArray = variables.countryCubes.map(d => d.name);

// Resultado final
return {
  indexDict,
  datasetsArray,

  subnatDatasetTime: resultTime.datasetName,
  lastTimeLevel,
  timeLevels: resultTime.levels,

  subnatDatasetProduct: resultProduct.datasetName,
  lastProductLevel,
  subnatProductLevels: resultProduct.levels,

  subnatDatasetPartner: resultPartner.datasetName,
  lastPartnerLevel,
  partnerLevels: resultPartner.levels,

  subnatDatasetGeo: resultGeo.datasetName,
  lastGeoLevel,
  geoLevels: resultGeo.levels
};

const {
  topoJson,
  iso3,
  projection,
  variant_name1
  } = variables;

let config = {   
  type: "Geomap",
  data: [{}],

  groupBy: `Subnat Geography`,
  zoom: true,
  topojsonId: d => d.properties.id.toString(),
  topojsonKey: "objects",
  tooltip: false,
  projectionPadding: "10px 10px 10px 20px",
  backgroundConfig: {
    fill: "transparent"
  },
  legend: false,
  shapeConfig: {
    Path: {
      fill: d => String(d.properties.id) === String(variables.id1) ? "#FED023" : "gray",
      opacity: d => String(d.properties.id) === String(variables.id1) ? 1 : 0.5,
      stroke: "#63737f",
      strokeWidth: 1
    }
  },
  fitFilter: d => String(d.properties.id) === String(variables.id1),
  controls: false,
  projection: projection,
  tiles: false,
  topojson: topoJson,
  ocean: false,
  total: false,
  zoom: false,
  zoomScroll: false,
}

if (iso3 === "gbr" || variant_name1 === "US Ports" || variant_name1 === "South Africa Ports") {
  config.fitFilter = undefined
  config.shapeConfig.Path.opacity = d => (d.geometry.type) === "Point" ? d.properties.id.toString() === variables.id1.toString() ? 1 : 0 : 1
}


return config

