const {
  ENV_PROFILE_PREFIX,
  variant_name1,
  attr_cube1
} = variables;

function toSingular(word, lang) {
  if (lang === "en") {
    if (word.endsWith("ies")) return word.slice(0, -3) + "y";
    if (word.endsWith("ses") || word.endsWith("xes") || word.endsWith("zes")) return word.slice(0, -2);
    if (word.endsWith("s") && !word.endsWith("ss")) return word.slice(0, -1);
    return word;
  } else if (lang === "es") {
    if (word.endsWith("es") && !["ces", "ges", "jes"].includes(word.slice(-3))) return word.slice(0, -2);
    if (word.endsWith("s") && word.length > 3) return word.slice(0, -1);
    return word;
  } else if (lang === "zh") {
    return word;
  }
  return word;
}

function toPlural(word, lang) {
  if (lang === "en") {

    if (word.endsWith("s")) {
      return word;
    }
    if (word.endsWith("y") && !["a", "e", "i", "o", "u"].includes(word[word.length - 2])) {
      return word.slice(0, -1) + "ies";
    }
    if (word.endsWith("x") || word.endsWith("z")) {
      return word + "es";
    }
    return word + "s";
  } else if (lang === "es") {
    if (!word.endsWith("s")) return word + "s";
    if (word.endsWith("z")) return word.slice(0, -1) + "ces";
    return word;
  } else if (lang === "zh") {
    return word; 
  }
  return word;
}

function extractISO3(cubeName) {
  const match = cubeName.match(/^[^_]*_[^_]*_([a-zA-Z]{3})/);
  return match ? match[1] : null;
}

const cubeName = variables.attr_cube1;
const iso3 = extractISO3(cubeName);
const countryName = translations[variant_name1][locale].countryName;
const countryLink = `<a href="/${locale}${ENV_PROFILE_PREFIX}/country/${iso3}">${countryName}</a>`;

const hierarchyName = translations[variant_name1][locale].hierarchyName;
const hierarchyNamePlural = toPlural(hierarchyName, locale).toLowerCase();
const hierarchyNameSingular = toSingular(hierarchyName, locale).toLowerCase();

const productType = attr_cube1.split("_").pop();

return {
  iso3,
  country: countryLink,
  hierarchyName,
  hierarchyNameSingularUpperCase: hierarchyNameSingular.charAt(0).toUpperCase() + hierarchyNameSingular.slice(1),
  hierarchyNamePlural,
  hierarchyNameSingular,
  productType
};

const {
  id1,
  attr_hierarchy1,
  excludedGeo
} = variables;

const {
  abbreviate
} = formatters;

const data = resp.data;

data.sort((a, b) => b["Trade Value ECI"] - a["Trade Value ECI"]);

// exclude llega como "Subnat Geography:04000US11,04000US60,..."
const [, excludeIdsRaw] = String(excludedGeo ?? "").split(":");

const excludeSet = new Set(
  (excludeIdsRaw ?? "")
    .split(",")
    .map(id => id.trim())
    .filter(Boolean)
);

const filteredData = excludeSet.size
  ? data.filter(item => !excludeSet.has(String(item[`${attr_hierarchy1} ID`])))
  : data;

const index = filteredData.findIndex(item => String(item[`${attr_hierarchy1} ID`]) === String(id1));

const length = filteredData.length;

if (index === -1) {
  return {
    eciValue: false,
    eciRank: 0,
    eciLen: length
  };
}

const value = filteredData[index]["Trade Value ECI"];
const roundedValue = typeof value === "number" ? Number(value.toFixed(2)) : false;

return {
  eciValue: roundedValue,
  eciRank: index + 1,
  eciLen: length
};

const data = resp.data;

// Detectar automáticamente el nombre del campo de tiempo
const firstRow = data[0] || {};
const timeField = firstRow.Time !== undefined ? "Time" : firstRow.Year !== undefined ? "Year" : null;

if (!timeField) {
  return {
    error: "No se encontró un campo temporal válido (Time o Year)"
  };
}

// Detectar formato de tiempo y extraer componentes
const getTimeComponents = time => {
  const timeStr = String(time);

  if (timeStr.length === 4) {
    return { 
      format: 'year',
      year: parseInt(timeStr, 10),
      quarter: null,
      month: null 
    };
  } else if (timeStr.length === 5) {
    return { 
      format: 'quarter',
      year: parseInt(timeStr.slice(0, 4), 10),
      quarter: parseInt(timeStr.slice(4), 10),
      month: null 
    };
  } else if (timeStr.length === 6) {
    return { 
      format: 'month',
      year: parseInt(timeStr.slice(0, 4), 10),
      quarter: Math.floor((parseInt(timeStr.slice(4), 10) - 1) / 3) + 1,
      month: parseInt(timeStr.slice(4), 10)
    };
  }

  return { format: 'unknown', year: null, quarter: null, month: null };
};

const quarterMonths = {
  1: [1, 2, 3],
  2: [4, 5, 6],
  3: [7, 8, 9],
  4: [10, 11, 12]
};

const yearData = {};
const allTimes = new Set();
const yearTimes = new Set();
const quarterTimes = new Set();
const monthTimes = new Set();

data.forEach(item => {
  const time = item[timeField];
  allTimes.add(time);

  const { format, year, quarter, month } = getTimeComponents(time);

  if (format === 'unknown' || !year) return;

  if (format === 'year') yearTimes.add(time);
  if (format === 'quarter') quarterTimes.add(time);
  if (format === 'month') monthTimes.add(time);

  if (!yearData[year]) {
    yearData[year] = { months: new Set(), quarters: new Set() };
  }

  if (format === 'quarter' && quarter) {
    yearData[year].quarters.add(quarter);
  } else if (format === 'month' && month) {
    yearData[year].months.add(month);
  }
});

const getCompleteQuarters = (monthsSet) => {
  return Object.entries(quarterMonths)
    .filter(([_, months]) => months.every(month => monthsSet.has(month)))
    .map(([quarter]) => quarter);
};

const fullYears = [];
const allQuarters = [];

Object.entries(yearData).forEach(([year, { months, quarters }]) => {
  if (yearTimes.has(parseInt(year, 10)) || quarters.size === 4 || months.size === 12) {
    fullYears.push(parseInt(year, 10));
  }

  quarters.forEach(q => allQuarters.push(`${year}${q}`));
  getCompleteQuarters(months).forEach(q => allQuarters.push(`${year}${q}`));
});

const sortedYears = [...fullYears].sort((a, b) => b - a);

const uniqueQuarters = [...new Set(allQuarters)].sort((a, b) => {
  const [yearA, quarterA] = [parseInt(a.slice(0, 4), 10), parseInt(a.slice(-1), 10)];
  const [yearB, quarterB] = [parseInt(b.slice(0, 4), 10), parseInt(b.slice(-1), 10)];
  return yearB !== yearA ? yearB - yearA : quarterB - quarterA;
});

const sortedMonths = [...monthTimes].sort((a, b) => b - a);
const sortedAllTimes = [...allTimes].sort((a, b) => b - a);

let latestYear = sortedYears[0] || null;
let previousYear = sortedYears[1] || null;

const latestQuarter = uniqueQuarters[0] || null;
let previousQuarter = null;

if (latestQuarter) {
  const year = parseInt(latestQuarter.slice(0, 4), 10);
  const quarter = latestQuarter.slice(4);
  const expectedPreviousQuarter = `${year - 1}${quarter}`;
  previousQuarter = uniqueQuarters.find(q => q === expectedPreviousQuarter) || null;
}

const latestMonth = sortedMonths[0] || null;
let previousMonth = null;

if (latestMonth) {
  const { year, month } = getTimeComponents(latestMonth);
  const expectedPreviousMonth = parseInt(`${year - 1}${String(month).padStart(2, '0')}`, 10);
  previousMonth = sortedMonths.find(time => time === expectedPreviousMonth) || null;
}

const latestTime = sortedAllTimes[0] || null;
let previousTime = null;

if (latestTime !== null) {
  const { format, year, quarter, month } = getTimeComponents(latestTime);

  if (format === 'year') {
    previousTime = sortedAllTimes.find(time => time === year - 1) || null;
  } else if (format === 'quarter') {
    const expectedPrevious = parseInt(`${year - 1}${quarter}`, 10);
    previousTime = sortedAllTimes.find(time => time === expectedPrevious) || null;
  } else if (format === 'month') {
    const expectedTime = parseInt(`${year - 1}${String(month).padStart(2, '0')}`, 10);
    previousTime = sortedAllTimes.find(time => time === expectedTime) || null;
  }
  if (!previousTime) {
    const index = sortedAllTimes.indexOf(latestTime);
    if (index !== -1 && index + 1 < sortedAllTimes.length) {
      previousTime = sortedAllTimes[index + 1];
    }
  }
}

if (!latestYear && latestTime) {
  latestYear = parseInt(String(latestTime).slice(0, 4), 10);
}

return {
  fullYears: sortedYears,
  fullQuarters: uniqueQuarters,
  fullMonths: sortedMonths,
  latestYear,
  previousYear,
  latestQuarter,
  previousQuarter,
  latestMonth,
  previousMonth,
  latestTime,
  previousTime: previousTime ? previousTime : 202001
};

