const safeSubtract = (a, b) => {
  try {
    if (typeof a !== "number" || typeof b !== "number") return false;
    return a - b;
  } catch (error) {
    console.error("Error in safeSubtract:", error.message);
    return false;
  }
};

const importsGrowthValue = safeSubtract(latestImports, previousImports);
const exportsGrowthValue = safeSubtract(latestExports, previousExports);
