const safeGrowthPercentage = (growthValue, previousValue) => {
  try {
    if (typeof growthValue !== "number" || typeof previousValue !== "number") return false;
    if (previousValue <= 0) return 0;
    return (growthValue / previousValue) * 100;
  } catch (error) {
    console.error("Error in safeGrowthPercentage:", error.message);
    return false;
  }
};

