    if (!abbreviate || typeof abbreviate !== "function") return false;

    const value = d["Trade Value"];
    if (typeof value !== "number") return false;

    return `(${currencySubnat}${abbreviate(value)})`;
  } catch (error) {
    console.error("Error in generateTradeValue:", error.message);
    return false;
  }
};

const generateGrowthValue = (d, locale, currencySubnat, abbreviateSubnat, growthPct) => {
  try {
    if (!d || typeof d !== "object") return false;
    if (!abbreviate || typeof abbreviate !== "function") return false;
    if (!growthPct || typeof growthPct !== "function") return false;

    const growthVal = d["Trade Value Growth Value"];
    const growthRate = d["Trade Value Growth"];

    if (typeof growthVal !== "number" || typeof growthRate !== "number") return false;

    const sign = growthVal < 0 ? "-" : "";
    const formattedValue = `${sign}${currencySubnat}${abbreviate(Math.abs(growthVal))}`;
    const formattedPct = growthPct(growthRate * 100);

