const latestImports = Array.isArray(resp?.[0]?.data) ? resp[0].data : [];
const latestExports = Array.isArray(resp?.[1]?.data) ? resp[1].data : [];

const importsGrowthPositive = Array.isArray(resp?.[2]?.data) ? resp[2].data : [];
const exportsGrowthPositive = Array.isArray(resp?.[3]?.data) ? resp[3].data : [];

const importsGrowthNegative = Array.isArray(resp?.[4]?.data) ? resp[4].data : [];
const exportsGrowthNegative = Array.isArray(resp?.[5]?.data) ? resp[5].data : [];

