// Nuevo: percentiles para datasets más pequeños
function getPercentileThresholds(data, key, lowerP = 0.05, upperP = 0.95) {
  const values = data.map(d => d[key]).filter(v => typeof v === 'number').sort((a, b) => a - b);
  if (values.length === 0) return { lowerThreshold: -Infinity, upperThreshold: Infinity };

  const lowerIndex = Math.floor(values.length * lowerP);
  const upperIndex = Math.floor(values.length * upperP);

  const lowerThreshold = values[lowerIndex];
  const upperThreshold = values[Math.min(upperIndex, values.length - 1)];

  return { lowerThreshold, upperThreshold };
}

