const dataFormatTradeValue = resp => {
  const data = normalizeTime(resp.data);

  const processFlow = flowID => {
    const filteredData = data.filter(d => d["Trade Flow ID"] === flowID);
    const prevData = generateAvailablePeriods(filteredData, timeScale);
    const finalData = calculatePreviousDate(prevData, periods);

    finalData.forEach(d => {
      d["Current Date"] = d.period;
      d["Current Time"] = subnatTimeOptions[timeScale][d["Current Date"]];
      d["Previous Time"] = subnatTimeOptions[timeScale][d["Previous Date"]];
      d["Trade Flow ID"] = flowID;
      d["Trade Flow"] = flowLabels[locale][flowID];
    });

    return finalData
      .map(item => generateTooltipDateNamesWithLocale(item, timeScale, locale))
      .filter(d => d["Trade Value"]);
  };

  return [...processFlow(2), ...processFlow(1)];
};

const dataFormatGrowth = resp => {
  const data = normalizeTime(resp.data);

  const filteredData = data.filter(d => d["Trade Flow ID"] === flowScale * 1);
  const groupedData = generateAvailablePeriods(filteredData, timeScale);
  const growthResults = calculateGrowth(groupedData, periods, filteredData);

  growthResults.forEach(d => {
    d["Trade Flow ID"] = flowScale;
    d["Trade Flow"] = flowLabels[locale][flowScale] || flowName;
  });

  return growthResults
    .map(item => generateTooltipDateNamesWithLocale(item, timeScale, locale))
    .filter(d => d["Trade Value Growth"]);
};

