// Detectar si el campo de tiempo es "Time" o "Year"
const sample = data[0] || {};
const timeField = sample.Time !== undefined ? "Time" : sample.Year !== undefined ? "Year" : null;

if (!timeField) {
    return { error: "No se encontró un campo temporal válido (Time o Year)" };
}

const result = data.reduce((acc, item) => {
    const timeValue = item[timeField];
    const timeStr = String(timeValue);
    const timeLength = timeStr.length;
    const year = timeStr.slice(0, 4);

    // Caso 1: Mes (YYYYMM)
    if (timeLength === 6) {
        if (!acc.Month) acc.Month = {};
        acc.Month[timeValue] = [timeValue];

        const month = timeStr.slice(4, 6);
        const monthNum = parseInt(month, 10);
        const quarterKey =
            monthNum <= 3 ? `${year}1` :
            monthNum <= 6 ? `${year}2` :
            monthNum <= 9 ? `${year}3` : `${year}4`;

        if (!acc.Quarter) acc.Quarter = {};
        if (!acc.Quarter[quarterKey]) acc.Quarter[quarterKey] = [];
        acc.Quarter[quarterKey].push(timeValue);

        if (!acc.Year) acc.Year = {};
        if (!acc.Year[year]) acc.Year[year] = [];
        acc.Year[year].push(timeValue);
    }

    // Caso 2: Trimestre (YYYYQ)
    else if (timeLength === 5) {
        if (!acc.Quarter) acc.Quarter = {};
        acc.Quarter[timeValue] = [timeValue];

        if (!acc.Year) acc.Year = {};
        if (!acc.Year[year]) acc.Year[year] = [];
        acc.Year[year].push(timeValue);
    }

    // Caso 3: Año (YYYY)
    else if (timeLength === 4) {
        if (!acc.Year) acc.Year = {};
        if (!acc.Year[year]) acc.Year[year] = [];
        acc.Year[year].push(timeValue);
    }

    return acc;
}, {});


