const combineData = (currData, prevData, countryIdKey) => {
  const prevDataMap = new Map(prevData.map(item => [item[countryIdKey], item]));
  return currData.map(currItem => {
    const prevItem = prevDataMap.get(currItem[countryIdKey]) || {};
    const combinedItem = {
      "Current Trade Value": currItem["Trade Value"],
      "Previous Trade Value": prevItem["Trade Value"] || 0,
      "Trade Value Growth Value": currItem["Trade Value"] - (prevItem["Trade Value"] || 0),
      "Trade Value Growth": prevItem["Trade Value"] === 0 ? false : 
        ((currItem["Trade Value"] - prevItem["Trade Value"]) / prevItem["Trade Value"]) * 100
    };
    return Object.assign(combinedItem, 
      Object.fromEntries(Object.entries(currItem).filter(([key]) => key !== "Trade Value")),
      Object.fromEntries(Object.entries(prevItem).filter(([key]) => key !== "Trade Value" && !(key in combinedItem)))
    );
  });
};

const transformDate = (currentDate, selector) => {
  currentDate = String(currentDate);
  const year = String(currentDate).slice(0, 4);
  const format = currentDate.length === 4 ? "Year" :
                 currentDate.length === 5 ? "Quarter" :
                 currentDate.length === 6 ? "Month" :
                 currentDate.length === 10 && currentDate.includes('/') ? "Date" :
                 (() => { throw new Error("Invalid currentDate format"); })();

  const getQuarter = month => Math.ceil(month / 3);
  const getMonthFromQuarter = quarter => ["01", "04", "07", "10"][quarter - 1];

  const transforms = {
    Year: { Year: year, Quarter: `${year}1`, Month: `${year}01` },
    Quarter: {
      Year: year,
      Quarter: currentDate,
      Month: `${year}${getMonthFromQuarter(currentDate.slice(4, 5))}`
    },
    Month: {
      Year: year,
      Quarter: `${year}${getQuarter(parseInt(currentDate.slice(4, 6), 10))}`,
      Month: currentDate
    },
    Date: {
      Year: year,
      Quarter: `${year}${getQuarter(parseInt(currentDate.split('/')[0], 10))}`,
      Month: `${year}${currentDate.split('/')[0]}`
    }
  };

  return transforms[format][selector] || (() => { throw new Error("Invalid selector"); })();
};

