function combineData(currData, prevData, countryIdKey) {
    const prevDataMap = new Map(prevData.map(item => [item[countryIdKey], item]));

    return currData.map(currItem => {
        const prevItem = prevDataMap.get(currItem[countryIdKey]) || {};

        const combinedItem = {
            "Current Trade Value": currItem["Trade Value"],
            "Previous Trade Value": prevItem["Trade Value"] || 0,
            "Trade Value Growth Value": (currItem["Trade Value"] - (prevItem["Trade Value"] || false)),
            "Trade Value Growth": prevItem["Trade Value"] === 0 ? false : 
                ((currItem["Trade Value"] - prevItem["Trade Value"]) / prevItem["Trade Value"]) * 100
        };

        Object.keys(currItem).forEach(key => {
            if (!combinedItem.hasOwnProperty(key) && key !== "Trade Value") {
                combinedItem[key] = currItem[key];
            }
        });

        Object.keys(prevItem).forEach(key => {
            if (!combinedItem.hasOwnProperty(key) && key !== "Trade Value") {
                combinedItem[key] = prevItem[key];
            }
        });

        return combinedItem;
    });
}

function transformDate(currentDate, selector) {
  currentDate = String(currentDate);
  const year = String(currentDate).slice(0, 4);
  let currentFormat, month, quarter;

  if (currentDate.length === 4) {
    currentFormat = "Year";
  } else if (currentDate.length === 5) {
    currentFormat = "Quarter";
    quarter = currentDate.slice(4, 5);
  } else if (currentDate.length === 6) {
    currentFormat = "Month";
    month = currentDate.slice(4, 6);
  } else if (currentDate.length === 10 && currentDate.includes('/')) {
    const [inputMonth, inputDay, inputYear] = currentDate.split('/');
    if (inputMonth.length === 2 && inputDay.length === 2 && inputYear.length === 4) {
      currentFormat = "Date";
      month = inputMonth;
    } else {
      throw new Error("Invalid MM/DD/YYYY format");
    }
  } else {
    throw new Error("Invalid currentDate format");
  }

  switch (currentFormat) {
    case "Year":
      switch (selector) {
        case "Year":
          return year;
        case "Quarter":
          return `${year}1`;
        case "Month":
          return `${year}01`;
      }
      break;

    case "Quarter":
      switch (selector) {
        case "Year":
          return year;
        case "Quarter":
          return `${year}${quarter}`;
        case "Month":
          const quarterToMonth = {
            "1": "01",
            "2": "04",
            "3": "07",
            "4": "10"
          };
          return `${year}${quarterToMonth[quarter]}`;
      }
      break;

    case "Month":
      switch (selector) {
        case "Year":
          return year;
        case "Quarter":
          quarter = 
            month <= "03" ? "1" :
            month <= "06" ? "2" :
            month <= "09" ? "3" : "4";
          return `${year}${quarter}`;
        case "Month":
          return `${year}${month}`;
      }
      break;

    case "Date":
      switch (selector) {
        case "Year":
          return year;
        case "Quarter":
          quarter = 
            month <= "03" ? "1" :
            month <= "06" ? "2" :
            month <= "09" ? "3" : "4";
          return `${year}${quarter}`;
        case "Month":
          return `${year}${month}`;
      }
      break;

    default:
      throw new Error("Invalid selector");
  }
}

