// Función para convertir YYYYMM a diferentes formatos
const processTimeData = (data, timeType) => {
  return data.map(d => {
    const timeStr = d.Time.toString();
    const year = parseInt(timeStr.substring(0, 4));
    const month = parseInt(timeStr.substring(4, 6));

    let processedData = { ...d };

    switch(timeType) {
      case "Year":
        processedData.Date = year;
        processedData["Date Name"] = year.toString();
        processedData.Year = year;
        break;

      case "Quarter":
        const quarter = Math.ceil(month / 3);
        processedData.Date = `${year}Q${quarter}`;
        processedData["Date Name"] = `Q${quarter} ${year}`;
        processedData.Year = year;
        processedData.Quarter = quarter;
        processedData["Quarter ID"] = quarter;
        break;

      case "Month":
      default:
        processedData.Date = `${month.toString().padStart(2, "0")}/01/${year}`;
        processedData["Date Name"] = `${[month]} ${year}`;
        processedData.Year = year;
        processedData.Month = [month];
        processedData["Month ID"] = month;
        break;
    }

    return processedData;
  });
};

// Función para agregar datos por período
const aggregateData = (data, timeType) => {
  const groupKey = timeType === "Year" ? "Year" : 
                   timeType === "Quarter" ? "Date" : // Ya procesado como YYYYQ#
                   "Date"; // Ya procesado como MM/01/YYYY

  const grouped = data.reduce((acc, d) => {
    const key = `${d[groupKey]}_${d["Trade Flow ID"]}`;

    if (!acc[key]) {
      acc[key] = {
        ...d,
        "Trade Value": 0
      };
    }

    acc[key]["Trade Value"] += d["Trade Value"];
    return acc;
  }, {});

  return Object.values(grouped);
};

return {
  axisPersist: false,
  data: url,
  dataFormat: resp => {
    let data = resp.data.map(d => ({ ...d }));

    // 1. Procesar datos temporales según el tipo seleccionado
    data = processTimeData(data, time);

    // 2. Agregar datos si es necesario (para Year y Quarter)
    if (time === "Year" || time === "Quarter") {
      data = aggregateData(data, time);
    }

    // 3. Filtrar datos según el período
    if (time === "Year") {
      data = data.filter(d => d.Year >= 2025);
    } else if (time === "Quarter") {
      data = data.filter(d => d.Year >= 2015);
    } else { // Month
      data = data.filter(d => d.Year >= 2015);
    }


    // 4. Separar importaciones y exportaciones
    const importData = data.filter(d => d["Trade Flow ID"] === 1);
    const exportData = data.filter(d => d["Trade Flow ID"] === 2);

    // 5. Calcular balanza comercial
    const trade = JSON.parse(JSON.stringify(importData));

    trade.forEach(d => {
      const dateKey = time === "Year" ? "Year" : "Date";
      const temp = exportData.find(h => h[dateKey] === d[dateKey]) || {};
      d["Export Value"] = temp["Trade Value"] || 0;
      d["Balance"] = d["Export Value"] - d["Trade Value"];
    });


    trade.forEach(d => {
      d["Trade Value"] = d["Balance"];
      delete d["Export Value"];
      delete d["Balance"];
      d["Trade Flow ID"] = 3;
      d["Trade Flow"] = "Balance comercial";
      d["Shape"] = "Line";
    });


    data.forEach(d => {
      d["Shape"] = "Bar";
      d["Trade Value"] = d["Trade Flow ID"] === 2 ? d["Trade Value"] : d["Trade Value"] * -1;
    });


    const flowLabel = {
      1: "Importaciones",
      2: "Exportaciones", 
      3: "Balance comercial"
    };


    let dataFinal = data.concat(trade);


    dataFinal.forEach(d => {
      d["Trade Flow"] = flowLabel[d["Trade Flow ID"]] || "N/A";
    });


    return dataFinal;
  },
