const buildTradeValueText = (value) => {
  try {
    if (typeof value !== "number" || !abbreviate) return false;
    return `${currencySubnat}${abbreviate(value)}`;
  } catch (error) {
    console.error("Error in buildTradeValueText:", error.message);
    return false;
  }
};

const buildGrowthValueText = (growthVal) => {
  try {
    if (typeof growthVal !== "number" || !abbreviate) return false;
    const sign = growthVal < 0 ? "-" : "";
    return `${sign}${currencySubnat}${abbreviate(Math.abs(growthVal))}`;
  } catch (error) {
    console.error("Error in buildGrowthValueText:", error.message);
    return false;
  }
};

const buildGrowthPctText = (growthRate) => {
  try {
    if (typeof growthRate !== "number" || !growthPct) return false;
    return growthPct(growthRate * 100);
  } catch (error) {
    console.error("Error in buildGrowthPctText:", error.message);
    return false;
  }
};

// entrada cruda -> objeto estructurado, sin descartar por signo (para las listas "latest")
const buildTradeEntry = (d) => {
  try {
    if (!d || typeof d !== "object") return false;
    const country = d["Country"];
    const tradeValue = d["Trade Value"];
    const link = buildLink(d);
    if (!country || link === false || typeof tradeValue !== "number") return false;

    return {
      country,
      link,
      tradeValue,
      tradeValueText: buildTradeValueText(tradeValue),
      formatted: `${link} (${buildTradeValueText(tradeValue)})`
    };
  } catch (error) {
    console.error("Error in buildTradeEntry:", error.message);
    return false;
  }
};

// entrada cruda -> objeto estructurado de growth, descartando signo incorrecto o cero
const buildGrowthEntry = (d, wantsPositive) => {
  try {
    if (!d || typeof d !== "object") return false;
    const country = d["Country"];
    const growthValue = d["Trade Value Growth Value"];
    const growthRate = d["Trade Value Growth"];
    if (!country || typeof growthValue !== "number" || typeof growthRate !== "number") return false;

    if (wantsPositive && growthValue <= 0) return false;
    if (!wantsPositive && growthValue >= 0) return false;

    const link = buildLink(d);
    if (link === false) return false;

    const growthValueText = buildGrowthValueText(growthValue);
    const growthPctText = buildGrowthPctText(growthRate);

    return {
      country,
      link,
      growthValue,
      growthRate,
      growthValueText,
      growthPctText,
      formatted: `${link} (${growthValueText} or ${growthPctText})`
    };
  } catch (error) {
    console.error("Error in buildGrowthEntry:", error.message);
    return false;
  }
};

const buildList = (dataArray, entryFn) => {
  try {
    if (!Array.isArray(dataArray)) return [];
    return dataArray.slice(0, 5).map(entryFn).filter(item => item !== false);
  } catch (error) {
    console.error("Error in buildList:", error.message);
    return [];
  }
};

const latestOrigins = buildList(latestImports, buildTradeEntry);
const latestDestinations = buildList(latestExports, buildTradeEntry);

const topGainersImports = buildList(importsGrowthPositive, d => buildGrowthEntry(d, true));
const topDeclinersImports = buildList(importsGrowthNegative, d => buildGrowthEntry(d, false));
const topGainersExports = buildList(exportsGrowthPositive, d => buildGrowthEntry(d, true));
const topDeclinersExports = buildList(exportsGrowthNegative, d => buildGrowthEntry(d, false));

// alias por dirección del total, para no romper el template actual
const topGrowthOrigins = importsWantsPositive ? topGainersImports : topDeclinersImports;
const topGrowthDestinations = exportsWantsPositive ? topGainersExports : topDeclinersExports;

const toFormattedArray = (list) => {
  const formatted = list.map(item => item.formatted);
  return formatted.length > 0 ? formatted : false;
};

return {
  // listas "crudas" con todos los campos, para el generador de texto
  latestOrigins,
  latestDestinations,
  topGainersImports,
  topDeclinersImports,
  topGainersExports,
  topDeclinersExports,

  // compatibilidad con el template/fórmula actual (strings ya armados)
  latestDestinationsArray: toFormattedArray(latestDestinations),
  latestOriginsArray: toFormattedArray(latestOrigins),
  topGrowthOrigins: toFormattedArray(topGrowthOrigins),
  topGrowthDestinations: toFormattedArray(topGrowthDestinations)
};

