const version = {en: "en-US", es: "es-CL", zh: "zh-CN"};

n = libs.d3plus.formatAbbreviate(n, version[locale]);

const dollarEnEs = n.charAt(0) === "-" ? n.replace("-", "-$") : `$${n}`
const dollarZh = n.charAt(0) === "-" ? n.replace("-", "-美元") : `美元${n}`
return locale !== "zh" ? dollarEnEs : dollarZh.replace('k', '千').replace('M', '百万').replace('B', '十亿').replace('T', '兆')

return n.reduce((str, item, i) => {

  const connector = {
    "en": ", and",
    "es": ", y",
    "zh": "和"
  };

  const space = {
    "en": " ",
    "es": " ",
    "zh": ""
  };

  const comma = {
    "en": ", ",
    "es": ", ",
    "zh": "，"
  };

  if (!i) str += item;
  else if (i === n.length - 1 && i === 1) str += `${connector[locale]}${space[locale]}${item}`;
  else if (i === n.length - 1) str += `${connector[locale]}${space[locale]}${item}`;
  else str += `${comma[locale]}${item}`;
  return str;
}, "");

const {
  curr,
  currMoe = 0,
  prev,
  prevMoe = 0
} = n;

let value;

if (currMoe || prevMoe) {
  const f1 = (-prev / curr ** 2) ** 2 * currMoe ** 2;
  const f2 = (1 / curr) ** 2 * prevMoe ** 2;
  value = Math.sqrt(f1 + f2);
} else
  value = (curr - prev) / prev;
return value * 100;

//return `${libs.d3plus.formatAbbreviate((n))}%`
const version = {en: "en-US", es: "es-CL", zh: "zh-CN"};

return `${libs.d3plus.formatAbbreviate(n, version[locale]).replace("t", "T")}%`

const {column, data} = n;
let scale;

let values = data.map(d => d[column])
values.sort(function (a,b){return a-b})
const low = Math.round(values.length * 0.05);
const high = values.length - low;
const valuesFiltered = values.slice(low,high);
const scale_ = Math.max(Math.abs(valuesFiltered[0]), Math.abs(valuesFiltered[valuesFiltered.length-1]))
scale = scale_ === 0 ? 1 : scale_

return scale;

if (locale === "zh") return `第${n}`;

const suffixesByLocale = {
    en: ["th", "st", "nd", "rd"],
    es: ["to", "er", "do", "ro"],
};
const suffixes = suffixesByLocale[locale] || suffixesByLocale.es;

const lastDigit = n % 10;
const lastTwoDigits = n % 100;
const isTeen = lastTwoDigits >= 11 && lastTwoDigits <= 13;
const suffix = !isTeen && lastDigit >= 1 && lastDigit <= 3
    ? suffixes[lastDigit]
    : suffixes[0];

return `${n}${suffix}`;

